package com.wipro.hibernate;import jakarta.persistence.*;import java.util.*;@Entity @Table(name="MULTI_CAR_OWNER") public class MultiCarOwner{@Id private int ownerId;private String ownerName;@OneToMany(cascade=CascadeType.ALL)@JoinTable(name="OWNER_CARS",joinColumns=@JoinColumn(name="OWNER_ID"),inverseJoinColumns=@JoinColumn(name="REGNO"))private List<CarDetail>cars=new ArrayList<>();public MultiCarOwner(){}public MultiCarOwner(int i,String n,List<CarDetail>c){ownerId=i;ownerName=n;cars=c;}}